}

.part {
  position: absolute;
  left: 1.5vmin;
  top: 6.5vmin;

  .circle {
    position: absolute;
    border-radius: 50%;
    background: var(--labs-sys-color-secondary);
    width: 14vmin;
    aspect-ratio: 1;
    box-shadow: 1vmin 0 3vmin hsla(0, 0%, 0%, 1);
    &:before {
      content: "";
      position: absolute;
      inset: 0.1vmin;
      border: 0.2vmin hsla(0, 0%, 100%, 0.3) solid;
      border-radius: inherit;
      background: conic-gradient(
        transparent,
        var(--light),
        transparent,
        var(--light),
        transparent,
        var(--light),
        transparent,
        var(--light),
        transparent,
        var(--light),
        transparent
      );
    }
  }

  .bolt {
    position: absolute;
    left: 2vmin;
    top: 5.7vmin;
    width: 1vmin;
    opacity: 0.8;
