        radial-gradient(5vmin at 50% 5%, transparent 40%, black 70%)
          var(--labs-sys-color-warn-container) center center no-repeat;
    }

    .plug-end {
      position: absolute;
      left: 5.8vmin;
      top: 8vmin;
      width: 2.5vmin;
      aspect-ratio: 2/5;
      border-radius: 0.8vmin;
      background: radial-gradient(
          1vmin 2vmin at 70% 50%,
          rgba(255, 255, 255, 0.25),
          transparent
        ),
        linear-gradient(to bottom, rgba(0, 0, 0, 0.9), transparent 30%),
        linear-gradient(
          to right,
          rgba(0, 0, 0, 0.3),
          transparent,
          rgba(0, 0, 0, 0.3)
        ),
        radial-gradient(
          10vmin at 50% 0%,
          transparent 40%,
          rgba(0, 0, 0, 0.5) 60%
        ),
        var(--labs-sys-color-warn-container);
    }

    .plug-cable {
      position: absolute;
      left: 6.4vmin;
      top: 14vmin;

      .plug-calbe-end {
        position: absolute;
        left: 0.8vmin;
        top: 8.7vmin;
        transform: rotate(-45deg);
        width: 1.5vmin;
        height: 3.3vmin;
        background: radial-gradient(
            at 50% 0%,
            transparent 40%,
            rgba(0, 0, 0, 0.9) 80%
          ),
          radial-gradient(1vmin at 100% 0%, rgba(0, 0, 0, 0.7), transparent),
          linear-gradient(
            to right,
            rgba(0, 0, 0, 0.5),
            transparent 60%,
            rgba(0, 0, 0, 0.5)
          ),
          var(--labs-sys-color-tertiary-container);
        border-radius: 2vmin;
      }

      &:after {
        content: "";
        position: absolute;
        border-radius: 3vmin;
        width: 1.2vmin;
        height: 10vmin;
        background: radial-gradient(
            2vmin at 110% 100%,
            var(--labs-sys-color-tertiary-container),
            transparent
          ),
          linear-gradient(
            to right,
            rgba(0, 0, 0, 0.5),
            transparent 40%,
            transparent 50%,
            transparent 60%,
            rgba(0, 0, 0, 0.5)
          ),
          var(--labs-sys-color-tertiary-container);
      }

      // circle
      &:before {
        content: "";
        position: absolute;
        background: radial-gradient(at 50% 0%, black 40%, rgba(0, 0, 0, 0.8));
        border-radius: 50%;
        border: 0.3vmin solid rgba(255, 255, 255, 0.3);
