    width: 20.4vmin;
    height: 1.6vmin;
    transform: rotate(43deg);
    transform-origin: center left;

    &:after {
      content: "";
      position: absolute;
      top: 0.6vmin;
      width: 17.5vmin;
      height: 0.4vmin;
      background: transparent;
      box-shadow: inset 0 0 0.3vmin rgba(0, 0, 0, 0.7);
      border-radius: 2vmin;
    }
  }

  .bridge-glass {
    position: absolute;
    height: 2.2vmin;
    width: 16vmin;
    background: linear-gradient(
        to right,
        transparent,
        hsla(0, 0%, 100%, 0.7),
        transparent
      ),
      linear-gradient(
        to right,
        hsla(0, 0%, 100%, 0.7),
        transparent,
        transparent
      );
    border: 2px solid hsla(0, 0%, 100%, 0.4);
    top: -0.45vmin;
    border-radius: 3vmin;
    mix-blend-mode: overlay;
    z-index: 1;

    .waveimage {
      position: absolute;
      top: -0.8vmin;
      left: 0;
      height: 3.5vmin;
      width: 20vmin;
      opacity: 0;
      animation: wave 10s linear infinite;
      animation-delay: 1s;
    }
  }

  .bridge-light {
    z-index: 1;
    filter: blur(6px);
    position: absolute;
    height: 1.5vmin;
    width: 16vmin;
    background: white;
    animation: bridgelight 10s linear infinite;
    animation-delay: 1s;
    border-radius: 4vmin;
    opacity: 0;
  }

  .bridge-light2 {
    z-index: 1;
    position: absolute;
    height: 0.5vmin;
    top: 0.5vmin;
    width: 17vmin;
    --s: #a4eaf8;
    background: linear-gradient(
      to right,
      var(--s) 20%,
      transparent 20%,
      var(--s) 50%,
      transparent 50%,
      var(--s) 80%,
      transparent 80%,
      var(--s) 90%,
      transparent 90%,
      transparent
    );
    background-size: 200% 100%;
    border-radius: 4vmin;
    animation: bridgelight2 1s linear infinite;
    background-position: -100vmin;
    opacity: 0;
    z-index: 100;
  }

  @keyframes bridgelight2 {
    from {
      background-position: -100vmin;
      opacity: 0;
    }

    to {
      background-position: 0;
      opacity: 1;
    }
  }

  @keyframes bridgelight {
    from {
      opacity: 0;
      width: 0;
    }

    2% {
      opacity: 1;
      width: 22vmin;
    }

    49% {
      opacity: 1;
      width: 22vmin;
    }
    50% {
      opacity: 0;
      width: 0;
    }

    50% {
      width: 22vmin;
    }
  }

  &.right {
    left: unset;
    right: 15vmin;
    .circle {
      transform: rotate(42deg);
    }

    .plug-cable {
      transform: scaleX(-1) translateX(-1.2vmin);
    }

    .bridge {
      transform: rotate(136.8deg);
    }
  }

  &.bottom {
    left: 17.4vmin;
    top: unset;
    bottom: 5vmin;
    .circle {
      transform: rotate(59deg);
    }

    .plug {
      transform: rotate(270deg) translateX(-14.1vmin);
    }

    .bridge {
      width: 25.5vmin;
      left: 6.9vmin;
      transform: rotate(270deg);
      background: linear-gradient(
