      &:after {
        width: 22vmin;
      }

      .waveimage {
        width: 28vmin;
      }

      .bridge-glass {
        width: 20vmin;
        top: -0.5vmin;
      }



      .bridge-light2 {
        width: 22vmin;
      }

    }
  }
}

