// Works in Chromium-based browsers ✅
// CSS Future Tip ✨ (Houdini 🧙‍♂️ property rule)
// Browser Check: https://caniuse.com/mdn-css_at-rules_property

@property --value {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}

@property --width-ratio {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

@property --scale {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

:root {
  --width: 12vmin;
  --duration: 10s;
  --size: 36vmin;
  @supports not (background: paint(foo)) {
    --duration: 4s;
  }
}

.rings {
  filter: url(#blurFilter);
  width: var(--size);
  aspect-ratio: 1;
  border-radius: 50%;
  position: relative;
  perspective: var(--size);

  &:before,
  &:after {
    content: "";
    position: absolute;
    inset: 0;
    background: rgba(255, 0, 0, 1);
    border-radius: 50%;
    --width-ratio: 1;
    border: calc(var(--width) * var(--width-ratio)) solid transparent;
    mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
    background: conic-gradient(
        from calc(var(--value) * 3),
        #ff8c41,
        transparent,
        #6666d2,
        #bb2727,
        #3bf6ff,
        transparent,
        transparent,
        #00a8ff,
        transparent,
        magenta,
        yellow,
        orange,
        transparent,
        transparent,
        transparent
      )
      border-box;
    mask-composite: exclude;
    @supports (background: paint(foo)) {
      animation: ring var(--duration) ease-in-out infinite;
    }
    @supports not (background: paint(foo)) {
      animation: ring-legacy var(--duration) ease-in-out infinite;
    }
    --start: 180deg;
    --value: var(--start);
    --scale: 1;
    transform: rotateY(var(--value)) rotateX(var(--value)) rotateZ(var(--value))
      scale(var(--scale));
  }

  &:before {
    --start: 180deg;
  }

  &:after {
    --start: 90deg;
  }

  > .rings {
    &:before {
      --start: 360deg;
    }

    &:after {
      --start: 270deg;
    }
  }
}

@keyframes ring {
  from {
    --value: var(--start);
    --scale: 1;
  }
  50% {
    --scale: 1.2;
    --width-ratio: 1.5;
  }
  70% {
    --scale: 1;
    --value: calc(var(--start) + 180deg);
    --width-ratio: 1;
  }

  80% {
    --scale: 1.2;
    --width-ratio: 1.5;
  }

  to {
    --value: calc(var(--start) + 360deg);
    --scale: 1;
    --width-ratio: 1;
  }
}

@keyframes ring-legacy {
  from {
    --value: var(--start);
    --scale: 1;
    transform: rotateY(var(--value)) rotateX(var(--value)) rotateZ(var(--value))
      scale(var(--scale));
  }

  70% {
    --scale: 1.2;
    --value: calc(var(--start) + 180deg);
    transform: rotateY(var(--value)) rotateX(var(--value)) rotateZ(var(--value))
      scale(var(--scale));
  }

  to {
    --value: calc(var(--start) + 360deg);
    --scale: 1;
    transform: rotateY(var(--value)) rotateX(var(--value)) rotateZ(var(--value))
      scale(var(--scale));
  }
}

.iris {
  display: grid;
