config.css:
$size: 4; // number of layers

:root {
  --size: 10vmin;
  --c2: #f672ca;
}

@layer props {
  @property --a {
    syntax: "<angle>";
    inherits: true;
    initial-value: 0deg;
  }
  @property --r {
    syntax: "<number>";
    inherits: true;
    initial-value: 0;
  }
  @property --r2 {
    syntax: "<number>";
    inherits: true;
    initial-value: 0;
  }
}

@layer animations {
  @keyframes angle {
    from {
      --a: 0deg;
    }
    to {
      --a: 360deg;
    }
  }

  @keyframes rotation {
    from {
      --r: 1;
    }

    50% {
      --r: 30;
    }

    to {
      --r: 1;
    }
  }

  @keyframes speak {
    from {
      --r2: 1;
    }
    10% {
      --r2: 0.6;
    }
    30% {
      --r2: 1;
    }

    40% {
      --r2: 0.3;
    }

    50% {
      --r2: 1;
    }

    60% {
      --r2: 0.6;
    }

    to {
      --r2: 1;
    }
  }
}

.scene {
  perspective: 100vmin;
  filter: drop-shadow(2px 4px 26px rgba(0, 100, 255, 0.5));
}

.cube {
  transform-style: preserve-3d;
  transform: translate3d(-5vmin, -8vmin, 0) scale(0);
  transition: all 0.3s ease;
  transition-delay: 0.5s;
  transform-origin: right;
  > div {
    opacity: 0;
    transition: opacity 0.3s ease;
    transition-delay: 0.3s;
    position: absolute;
    width: var(--size);
    height: var(--size);

    &:not(.bottom) {
      transform-origin: bottom;
    }
  }

  .front {
    background: linear-gradient(#111, #0f68ff) no-repeat,
      linear-gradient(#111, #0f68ff) no-repeat,
      linear-gradient(#111, #0f68ff) no-repeat, #e472f6;
    background-size: 8vmin calc(2.5vmin * var(--r2, 1)), 3vmin 2vmin,
      3vmin 2vmin;
    background-position: 1vmin 6vmin, 1vmin 2vmin, 6vmin 2vmin;
    transform: translateZ(calc(var(--size) / 2));
  }

  .back {
    background: #3b90b5;
    transform: translateZ(calc(var(--size) / -2));
  }

  .left {
    background: #ffffff;
    transform: translateX(-50%) rotateY(90deg);
  }

  .right {
    background: #7597f9;
    transform: translateX(50%) rotateY(90deg);
  }

  .bottom {
    background: #0f68ff;
    transform: rotateX(-90deg) translateZ(calc(var(--size) / 2));
  }
}

.object {
  transform-style: preserve-3d;
  transform: rotate3d(0, 1, 0, var(--a)) translateY(-3vmin);
  animation: angle 10s ease infinite;
  --r: 1;
  height: calc(#{$size} * var(--size) * 4);

  &.expand {
    animation: angle 10s ease infinite, rotation 6s cubic-bezier(1, -1.45, 0.45, 2.25),
      speak 0.6s linear infinite;
    @supports (animation-timing-function: linear(0, 1)) {
      animation: angle 10s ease infinite,
        rotation 6s
          linear(
            -0.0924,
            -0.03451 3.63%,
            -0.06267 4.48%,
            -0.12996 7.271%,
            -0.13982 7.281%,
            -0.05002 10.911%,
            -0.06745 12.721%,
            -0.07998 14.541%,
            -0.12402 14.551%,
            0.3452 21.812%,
            0.4712 25.253%,
            0.63076 29.003%,
            0.80801 32.683%,
            1.00519 36.354%,
            0.96732 37.594%,
            0.90059 40.434%,
            0.85372 42.834%,
            0.81542 45.245%,
            0.78696 47.555%,
            0.7665 49.875%,
            0.75421,
            0.75 54.495%,
            0.75376,
            0.76539,
            0.78487,
            0.81223 63.616%,
            0.84727 65.887%,
            0.89032 68.167%,
            1 72.727%,
            0.97268,
            0.95316 77.268%,
            0.9414 79.548%,
            0.9375,
            0.9414,
            0.95309,
            0.97258 88.629%,
            1 90.909%,
            0.98829,
            0.98438,
            0.98826 97.72%,
            1
          ),
        speak 0.6s linear infinite;
    }
    .cube {
      transform: translate3d(-5vmin, -8vmin, 0) scale(1);

      > div {
        opacity: 0.42;
      }
    }
  }
}

.top-triangle,
.bottom-triangle {
  transform-style: preserve-3d;
  height: calc(#{$size} * var(--size) * 1.5);
  transform: translateY(50%) translateX(-5vmin);
}

.bottom-triangle {
  transform: translateY(-60%) scaleY(-1) translateX(-5vmin);
}

.pyramid {
  position: absolute;
  transform-style: preserve-3d;
  width: var(--size);
  height: var(--size);
  $index: 1;
  @for $level from 1 through $size {
    $levelZ: $level / $index;
    $itemsPerLevel: $level * $level;
    $levelY: $level - round($size / 2);
    $center: round($level / 2);
    @for $x from 1 through $level {
      $cX: $x - $center;

      @if $level % 2 == 0 {
        $cX: $cX - 0.5;
      }

      @for $y from 1 through $level {
        $cY: $y - $center;

        @if $level % 2 == 0 {
          $cY: $cY - 0.5;
        }

        &:nth-child(#{$index}) {
          --index: #{$index};
          $offsetPerItem: calc(360deg / #{$level * $level});
          @if $level == 1 {
            --levelYCorrection: var(--r);
          }
          transform: translate3d(
            calc(var(--size) * #{$cX} * var(--r)),
            calc(8.5vmin * #{$levelY} * var(--levelYCorrection, 1)),
            calc(var(--size) * #{$cY} * var(--r))
          );
        }
        $index: $index + 1;
      }
    }
  }

  > div {
    position: absolute;
    width: var(--size);
    height: var(--size);
    opacity: 0.42;

    &:not(.bottom) {
      -webkit-mask: url("https://assets.codepen.io/907471/triangle-mask.svg")
        center center no-repeat;
      mask: url("https://assets.codepen.io/907471/triangle-mask.svg") center
        center no-repeat;
      mask-size: cover;
      -webkit-mask-size: cover;
      transform-origin: bottom;
    }
  }
}

.front {
  background: #e472f6;
  transform: translateZ(calc(var(--size) / 2)) rotateX(30deg);
}

.back {
  background: #3b90b5;
  transform: translateZ(calc(var(--size) / -2)) rotateX(-30deg);
}

.left {
  background: #ffffff;
  transform: translateX(-50%) rotateY(90deg) rotateX(-30deg);
}

.right {
  background: #7597f9;
  transform: translateX(50%) rotateY(90deg) rotateX(30deg);
}

.bottom {
  background: #0f68ff;
  transform: rotateX(-90deg) translateZ(calc(var(--size) / 2));
}

body {
  cursor: pointer;
  width: 100vw;
  height: 100vh;
  display: grid;
  place-items: center;
  background: radial-gradient(#1a2f47, #000000);
  color: var(--c2);
  margin: 0;
  overflow: hidden;
}

* {
  box-sizing: border-box;
