config.js:
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const getRandomInt = (max) => Math.floor(Math.random() * max);
const lineWidth = 2;
const gap = 5;
const colorPool = [
  "#3B82F6",
  "#B25FEA",
  "#5D5CDE",
  "#5E5CDD",
  "#EB5545",
  "#F8D74A",
  "#6BD35E",
  "#F8D74A",
  "#F1A33C",
  "#7EBED6",
  "#98989C",
  "#EB4A63"
];
const circleSize = 4;
const circleLineWidth = 3;
const circleCountPool = [0, 0, 0, 0, 1, 0, 0, 0, 0, 3, 0, 0, 0];

let reducedColorPool = [...colorPool];

const getColor = () => {
  if (reducedColorPool.length === 0) {
    reducedColorPool = [...colorPool];
  }
  return reducedColorPool.splice(getRandomInt(reducedColorPool.length),1)[0];
};

const render = () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, w, h);
  const lineCount = Math.round(w / lineWidth / gap);
  for (let i = 0; i < lineCount; i++) {
    // line
    const c = getColor();
    const curveY = (lineCount - 1 - i) * gap;
    let curveYDistance = 10;
    const lineX = gap + i * lineWidth * gap;
    const lineY = curveY + curveYDistance * 6;
    ctx.fillStyle = c;
    ctx.fillRect(lineX, lineY, lineWidth, h);

    // curve
    let start = { x: 0, y: curveY - i * 2 };
    let cp1 = { x: 0, y: curveY + curveYDistance + 10 };
    let cp2 = { x: lineX + 1, y: curveY + curveYDistance * 2 + 20 };
    let end = { x: lineX + 1, y: curveY + curveYDistance * 3 + 30 };

    ctx.beginPath();
    ctx.lineWidth = lineWidth;
    ctx.moveTo(start.x, start.y);
    ctx.bezierCurveTo(cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
    ctx.strokeStyle = c;
    ctx.stroke();

    // circles

    const circleCount = circleCountPool[getRandomInt(circleCountPool.length)];

    for (let c = 0; c < circleCount; c++ /* ¯\_(ツ)_/¯ */) {
      const circleY = getRandomInt(h) + c * 10; /*gap between circles*/
      if (circleY < lineY + gap) {
        continue;
      }
      ctx.beginPath();
      ctx.strokeStyle = "white";
      ctx.fillStyle = "#111";
      ctx.lineWidth = circleLineWidth;
      ctx.arc(
        lineX + 1,
        circleY,
        circleSize,
        0,
        2 * Math.PI
      );
      ctx.stroke();
      ctx.fill();
    }
  }
  let gradient = ctx.createLinearGradient(0, 0, 0, h);
  gradient.addColorStop(0, "transparent");
  gradient.addColorStop(0.4, "transparent");
  gradient.addColorStop(1, "black");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, w, h);

  gradient = ctx.createLinearGradient(0, 0, w/2, h/2);
  gradient.addColorStop(0, "black");

  gradient.addColorStop(.42, "transparent");

  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, w, h);
};

const update = () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  render();
};

window.addEventListener("resize", update);
canvas.addEventListener("pointerdown", render);
(() => {
  requestAnimationFrame(update);
})();

config.css:
@property --a {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: true;
}

$count: 24;

:root {
  --size: 140deg;
}

.container {
  display: flex;
  width: 100dvw;
  height: 100dvh;
  --count: #{$count};
  --per-item: #{50% / $count};
  --p-per-item: #{1 / $count};
  animation: main 12s cubic-bezier(0.83,-0.49, 0.15, 1.84) infinite;
}

@keyframes main {
  from {
    --a: 0deg;
  }
  to {
    --a: 360deg;
  }
}

.col {
  flex: 1;
  --a-per-item: calc(var(--size) / var(--count) * var(--i) - var(--a));
  --pos1: calc(50% * cos(var(--a-per-item)));
  background: linear-gradient(
to bottom,
    orange,
    magenta var(--pos1),
    #03072c 50%,
    magenta calc(100% - var(--pos1)),
    orange,
  );

  @for $i from 0 through $count - 1 {
    &:nth-child(#{$i + 1}) {
      --i: #{$i};
    }
  }
}

body {
  margin: 0;
  overflow: hidden;


  &:after {
    content: "";
    opacity: .5;
    position: absolute;
    background: url(https://assets.codepen.io/907471/noise.svg);
    mix-blend-mode: hue;
    inset: 0;
    pointer-events: none;
    filter: invert(1) brightness(5) saturate(.5);
  }
}

* {
  box-sizing: border-box;
}

@use 'sass:list';

:root {
  --color-primary: white;
  --color-surface: #030303;
}


@function highlight($gap, $size: 0.25vmin, $color: var(--c)) {
  @return -#{$gap $gap / 1.5 $size $color};
}

@function highlights() {
  $result: ();
  $gap: 0.25vmin;
  $count: 20;
  @for $i from $count through 0 {
    @if ($i == $count) {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.01vmin, var(--c2)),
        "comma"
      );
    } @else if ($i == $count - 1) {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.1vmin, rgba(255, 255, 255, 0.9)),
        "comma"
      );
    } @else {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.025vmin, var(--c)),
        "comma"
      );
    }
  }
  @return $result;
}

