.fab-container {
  position: absolute;
  inset: 0;
  border-radius: var(--md-frame-shape-radius);

  &:before {
    content: "";
    position: absolute;
     border-radius: var(--md-frame-shape-radius);
    inset: 0;
    background: linear-gradient(#3a6a1e14, #3a6a1e14),
      var(--md-sys-color-surface);
