    transition: opacity 0.1s ease;
    transition-delay: 0.3s;

    svg {
      width: 1.5rem;
    }
  }

  .fab-overlay {
    z-index: 2;
    position: absolute;
    left: var(--left, unset);
    top: var(--top, unset);
    right: 0.5rem;
    bottom: 5.5rem;
    background: var(--md-sys-color-secondary-container);
    border-radius: var(--md-fab-shape-radius);
  }

  &.expanded {
    .close {
      transition: 0.3s ease;
