      z-index: -1;
      position: absolute;
      opacity: 0.9;
    }
  }

  @function move($x, $y, $x2, $y2) {
    @return calc(#{$x} + (#{$x2} * var(--bg-x)))
      calc(#{$y} + (#{$y2} * var(--bg-y)));
  }

  @function move2($x, $y, $x2, $y2) {
    @return calc(#{$x} + (#{$x2} * var(--bg-x2)))
      calc(#{$y} + (#{$y2} * var(--bg-x2)));
  }

  .r1 {
    background: #93c9cc;
    width: 25vmax;
    border-radius: 50%;
    aspect-ratio: 4 / 2;
    translate: move(-4vmax, -30vmax, -4vmax, -3rem);
    rotate: calc(45deg * var(--bg-x2));
  }

  .r2 {
    background: #aab896;
    width: 35vmax;
    border-radius: 50%;
    aspect-ratio: 1.5 / 3;
    translate: move(-35vmax, -25vmax, -2vmax, 2rem);

    rotate: calc(15deg * var(--bg-x));
  }

  .r3 {
    background: radial-gradient(#334c74, transparent);
    width: 35vmax;
    border-radius: 20%;
    aspect-ratio: 2 / 3;
    translate: move(-5vmax, 5vmax, -5vmax, -2vmax);
    rotate: -35deg;
    opacity: calc(var(--bg-x));
  }

  .r4 {
    background: #d7cbc7;
    width: 25vmax;
    border-radius: 50%;
    aspect-ratio: 2 / 3;
    translate: move(10vmax, 7vmax, 7vmax, -5vmax);
    rotate: 35deg;
  }

  .r5 {
    background: rgba(105, 133, 87, 0.54);
    width: calc(35vmax + 2vmax * var(--bg-x2));
    border-radius: 50%;
    aspect-ratio: 5 / 3;
    translate: move2(22vmax, -9vmax, 2vmax, -2vmax);
    rotate: calc(-35deg * var(--bg-x));
  }

  .r6 {
    background: rgba(127, 190, 192, 0.64);
    width: 65vmax;
    border-radius: 50%;
    aspect-ratio: 6 / 2;
    translate: -35vmax 35vmax;
    rotate: calc(-35deg * var(--bg-x2));
  }

  .r7 {
    background: rgba(217, 193, 247, 0.72);
    width: calc(30vmax - 5vmax * var(--bg-x));
    border-radius: 50%;
    aspect-ratio: 1;
    translate: move(-15vmax, -30vmax, 3vmax, -1vmax);
    rotate: 35deg;
  }

  .r8 {
    background: rgba(217, 193, 247, 0.52);
    width: 40vmax;
    border-radius: 50%;
    aspect-ratio: 2 / 1;
    translate: move(24vmax, 30vmax, 5vmax, 5vmax);
    rotate: calc(35deg * var(--bg-x));
  }

  .r9 {
    background: rgba(105, 133, 87, 0.59);
    width: 30vmax;
    border-radius: 50%;
    aspect-ratio: 1 / 1.2;
    translate: move(44vmax, -10vmax, -4vmax, 1vmax);
    rotate: calc(35deg * var(--bg-x2));
  }

  .r10 {
    background: rgba(255, 255, 255, 1);
    width: 10vmax;
    border-radius: 50%;
    aspect-ratio: 1 / 1.2;
    translate: move(12vmax, 14vmax, -4vmax, 5vmax);
    rotate: calc(42deg * var(--bg-x2));
  }

  .r11 {
    background: rgba(255, 255, 255, 0.7);
    width: 20vmax;
    border-radius: 50%;
    aspect-ratio: 1 / 1.2;
    translate: move(-12vmax, -14vmax, 4vmax, 5vmax);
    rotate: calc(42deg * var(--bg-x2));
  }
}

@layer card {
  @keyframes card-enter {
    from {
      opacity: 0.01;
      transform: scale(0.9);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }
  .card {
    -webkit-backdrop-filter: blur(2rem) brightness(1.054) saturate(1);
    backdrop-filter: blur(2rem) brightness(1.054);
    border-radius: 1rem;
    animation: card-enter 0.45s ease-in forwards;
    display: grid;
    place-items: center;
    color: white;
    font-size: 2rem;
    border: 1px solid rgba(255, 255, 255, 0.25);
    box-shadow: -1px -1px 1px rgba(0, 0, 0, 0.04),
      1px 1px 0 1px rgba(0, 0, 0, 0.01);
    z-index: 100;
    --size: 2rem;
    --s: 36%;
    --d: 3deg;
    --x: calc(100% - var(--size));
    --y: 0;

    --s2: 28%;
    --d2: -148deg;
    --x2: var(--size);
    --y2: 100%;
    --mask: exclude;

    mask: conic-gradient(
        from var(--d2) at var(--x2) var(--y2),
        black var(--s2),
        transparent var(--s2)
      ),
      conic-gradient(
        from var(--d) at var(--x) var(--y),
        transparent var(--s),
        black var(--s)
      );
    -webkit-mask-composite: var(--mask);
    mask-composite: var(--mask);

    &::before {
      content: ""; // top left corner lines
      --c: rgba(0, 0, 0, 0.05);
      background: radial-gradient(
          0.09rem 2rem at 0 2.5rem,
          var(--c),
          transparent
        ),
        radial-gradient(2rem 0.09rem at 2.5rem 0, var(--c), transparent);
      position: absolute;
      inset: 0;
      z-index: 1;
    }

    &.full-shape {
      mask: unset;
    }
  }
}

