    width: 55vmin;
    aspect-ratio: 1;
    border-radius: 50%;
    filter: blur(0.5rem);
    pointer-events: none;

    &:after {
      @include hexagon-shape;
      content: ""; // outline - white highlighting
      box-shadow: inset 0 0 8vmin rgba(255, 255, 255, 0.5);
      position: absolute;
      inset: 3rem;
      filter: blur(0.5rem);
    }
  }

  .sphere-blur {
    position: absolute;
    inset: 0;
    -webkit-backdrop-filter: blur(4rem) saturate(1.1);
