    aspect-ratio: 1;
    --line-1-a: -45deg;
    --line-thickness: 69.5%;
    --line-2-p: 10%;
    mask-image: radial-gradient(
      transparent var(--line-thickness),
      black var(--line-thickness)
    );
    background: conic-gradient(
        from var(--line-1-a),
        var(--c),
        var(--c) 10%,
        transparent 12%
      ),
      conic-gradient(
        from 50deg,
        var(--c),
        var(--c) var(--line-2-p),
        transparent calc(var(--line-2-p) + 5%)
      ),
      conic-gradient(from 200deg, var(--c), var(--c) 10%, transparent 15%);
