@layer bars {
  @property --target {
    syntax: "<percentage>";
    inherits: true;
    initial-value: 0;
  }

  .bars {
    width: 19vmax;
    z-index: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    justify-content: center;
    color: white;
    position: absolute;

    .bar {
      width: 100%;
      height: 0.25rem;
      animation: bars 2.5s ease-in-out infinite;
      -webkit-backdrop-filter: blur(2rem) brightness(1.06) saturate(1);
      backdrop-filter: blur(2rem) brightness(1.06) saturate(1);

      &:after {
        content: "42-2024-123-123-42";
        font-size: 0.4rem;
      }

      &:first-of-type {
        width: 46%;
        animation-delay: 0.3s;
        --target: 120%;
      }

      &:last-of-type {
        width: 57%;
        animation-delay: 0.6s;
        animation-duration: 2.4s;
      }
    }

    &.left {
      left: 0;

      .bar {
        transform-origin: left;
      }
    }

    &.right {
      right: 0;
      align-items: flex-end;

      .bar {
        transform-origin: right;
      }
    }
  }

  @keyframes bars {
    from {
      transform: scaleX(100%);
    }

    30% {
      transform: scaleX(120%);
    }

    50% {
      transform: scaleX(var(--target, 90%));
    }

    to {
      transform: scaleX(100%);
    }
  }
}

@layer dna {
  $count: 50;
  @property --rotate-y {
    syntax: "<angle>";
    inherits: true;
    initial-value: 0deg;
  }

  @keyframes dna {
    from {
      --rotate-y: 0deg;
    }
    to {
      --rotate-y: 360deg;
    }
  }

  @property --rotate-container {
    syntax: "<angle>";
    inherits: true;
    initial-value: 0deg;
  }

  @keyframes rotate-container {
    from {
      --rotate-container: 42deg;
    }
    50% {
      --rotate-container: 142deg;
    }
    to {
      --rotate-container: 42deg;
    }
  }

  .dna-container {
    filter: url(#blurFilter) contrast(1.5) brightness(1.5) saturate(0.6);
    position: absolute;
    transform: scale(0.55);

    @media (max-width: 1000px) {
      transform: scale(0.25);
    }

    @media (max-height: 1000px) {
      transform: scale(0.25);
    }
  }

  .dna {
    --width: 14rem;
    --count: #{$count};
    display: flex;
    flex-direction: column;
    z-index: 1111;
    perspective: 45rem;
    animation: dna 4s linear infinite, rotate-container 30s ease-in-out infinite;
    transform-style: preserve-3d;
    rotate: var(--rotate-container);
    transform: rotateY(var(--rotate-y, 0deg));
    @media (prefers-reduced-motion) {
      animation: unset;
    }

    .item {
      display: flex;
      align-items: center;
      transform-style: preserve-3d;

      > div {
        width: var(--width);
        height: 0.42rem;
        background: rgba(255, 255, 255, 1);
        background: conic-gradient(
          color-mix(
            in oklch,
            color-mix(in oklch, var(--color-primary), white 6%),
            transparent 10%
          ),
          color-mix(in oklch, var(--color-secondary), black 6%)
        ); // remove to get 60fps
        transform-style: preserve-3d;

        &:first-of-type,
        &:last-of-type {
          --thickness: 0.9rem;
          width: var(--thickness);
          height: var(--thickness);
          background: var(--color-secondary);
          border-radius: 50%;

          @keyframes dot-scale {
            from {
              transform: scale(1);
            }
            50% {
              transform: scale(0.6);
            }
            to {
              transform: scale(1);
            }
          }

          &::before,
          &::after {
            content: "";
            position: absolute;
            width: calc(var(--thickness) * 0.5);
            border-radius: 50%;
            aspect-ratio: 1;
            transform-style: preserve-3d;
          }

          &::before {
            background: white;
            width: calc(var(--thickness) * 0.9);
            left: -0.4rem;
            top: -0.4rem;
            animation: dot-scale 2s ease-in-out infinite;
          }

          &::after {
            background: rgba(0, 0, 0, 0.09);
            right: 0.3rem;
            bottom: 0.3rem;
          }
        }

        &:last-of-type {
          background: var(--color-primary);
        }
      }

      --a: calc(360deg / var(--count) * (var(--i)));
      transform: rotateY(var(--a));

      > div {
        &:first-of-type,
        &:last-of-type {
          transform: rotateY(
            calc(360deg / var(--count) * -1 * var(--i) - var(--rotate-y))
          );
        }
      }

      @for $i from 0 through $count {
        &:nth-child(#{$i + 1}) {
          --i: #{$i};
        }
      }
    }
  }

  .dna-shadow {
    width: 12rem;
    height: 100%;
    filter: blur(3.5rem);
    background: radial-gradient(
        8rem 66% at 50% 40%,
        var(--color-primary),
        transparent 90%
      )
      center top / 14rem 33%;
    animation: rotate-container 30s ease-in-out infinite;
    rotate: var(--rotate-container);
    opacity: 1;
    @media (max-width: 1000px) {
      transform: scale(0.5);
    }
    @media (max-height: 1000px) {
      transform: scale(0.5);
    }
  }
}

@layer dashboard {
  .dashboard {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  perspective: 100px;
  transform: rotateY(0deg);
  translate: 0 0;

  &.show {
    animation: dashboard-enter .5s ease-in-out forwards, dashboard-rotation 5s .5s ease-in-out infinite;
  }

  &.hide {
    animation: dashboard-leave .5s ease-in-out forwards;
  }
}


@keyframes dashboard-rotation {
  from {
    transform: rotateY(59deg) rotateX(0);
  }
  50% {
    transform: rotateY(65deg) rotateX(-2deg);
  }
  to {
    transform: rotateY(59deg) rotateX(0);
  }
}

@keyframes dashboard-enter {
  80% {
    transform: rotateY(0);
  }
  to {
    transform: rotateY(59deg);
    translate: -50% 0;
  }
}

@keyframes dashboard-leave {
  0% {
    transform: rotateY(59deg);
    translate: -50% 0;
