			height: 0.2rem;
			border-radius: 50%;
			box-shadow: 0 -0.04rem 0 0 var(--c);
			translate: 0 -0.1rem;

			&:first-child {
				width: 0.25rem;
				translate: 0 -0.4rem;
			}

			&:last-child {
				width: 0.28rem;
				translate: 0 -0.25rem;
			}
