			mask: linear-gradient(to bottom right, transparent 50%, black 50%) no-repeat
					left / 50% 100%,
				linear-gradient(to top right, black 50%, transparent 50%) no-repeat right /
					50% 100%;

			&.left {
				transform: rotate(55deg) translate(-0.2rem, 0.5rem);
			}

			&.right {
				transform: rotate(-55deg) translate(0.2rem, 0.5rem);
			}
		}
	}

	// Triangle with CSS 🔥: https://alvaromontoro.com/blog/67970/drawing-a-triangle-with-css

	.mouth {
		z-index: 1;
		position: absolute;
		display: grid;
		place-items: center;

		&:after {
			content: ""; // triangle + stripes
			position: absolute;
			width: 1rem;
			height: 0.6rem;
			--g: 0.077rem;
			background: repeating-linear-gradient(
				to right,
				rgba(0, 0, 0, 0.1),
				rgba(0, 0, 0, 0.1) var(--g),
				var(--c) var(--g),
				var(--c) calc(var(--g) * 2)
			);
			mask: linear-gradient(to bottom right, transparent 50%, black 50%) no-repeat
					left center / 50% 100%,
				linear-gradient(to top right, black 50%, transparent 50%) no-repeat right
					center / 50% 100%;
			translate: 0 0.35rem;
		}

		.circles {
			position: absolute;
			display: grid;
			place-items: center;

			&:before,
			&:after {
				content: "";
				position: absolute;
				width: 0.1rem;
				aspect-ratio: 1;
				background: var(--c);
				border-radius: 50%;
				opacity: 0.6;
			}

			&:before {
				translate: -0.67rem 0.68rem;
			}

			&:after {
				translate: 0.67rem 0.68rem;
			}
		}

		.lines {
			position: absolute;
			display: grid;
			place-items: center;

			&:before,
			&:after {
				content: "";
				position: absolute;
				width: 0.7rem;
				height: 0.02rem;
				background: var(--c);
				opacity: 0.6;
			}

			&:before {
				transform: rotate(-52deg) translate(-0.5rem, -0.1rem);
			}

			&:after {
				transform: rotate(52deg) translate(0.5rem, -0.1rem);
			}
		}
	}

	.body {
		position: absolute;
		display: grid;
		place-items: center;
		overflow: hidden;
		background: rgba(0, 0, 0, 0.1);
		width: 2rem;
