config.js:
import { Pane } from "https://cdn.jsdelivr.net/npm/tweakpane@4.0.5/dist/tweakpane.min.js";


// https://tweakpane.github.io/docs/quick-tour/
const pane = new Pane({title: "Config", expanded: false})

const config = {
    global: {
        colorPrimary: '#ff3c3c',
        colorSecondary: '#75d8ee',
        colorOnSecondary: '#2a2a2a',
        colorOnSurface: '#a1a1a1',
        colorSurface: '#1d1d1d',
    },
    lightsaber: {
        width: .28,
        length: 5.6,
        rotateX: 0.01,
        rotateY: 0.01,
        rotateZ: 0.01,
        gripgap: 0.7,
        animate: true,
    },
}

const p = (name, value) => {
    document.documentElement.style.setProperty(`--${name}`, value);
}

const global = pane.addFolder({title: 'Global', expanded: true});
global.addBinding(config.global, 'colorPrimary').on('change', ({value}) => p('color-primary', value));
global.addBinding(config.global, 'colorOnSecondary').on('change', ({value}) => p('color-on-secondary', value));
global.addBinding(config.global, 'colorSecondary').on('change', ({value}) => p('color-secondary', value));
global.addBinding(config.global, 'colorOnSurface').on('change', ({value}) => p('color-on-surface', value));
global.addBinding(config.global, 'colorSurface').on('change', ({value}) => p('color-surface', value));

const lightsaber = pane.addFolder({title: 'Lightsaber', expanded: true});
['x', 'y', 'z'].forEach(key => {
    lightsaber.addBinding(config.lightsaber, `rotate${key.toUpperCase()}`, {min: -360, max: 360, step: .01})
        .on('change', ({value}) => p(`lightsaber-rotate-${key}`, value ? `${value}deg` : '0deg'));
});
lightsaber.addBinding(config.lightsaber, 'animate', {min: 0.1, max: 10, step: .1})
    .on('change', ({value}) => p('lightsaber-animation', value ? `main 5s linear infinite` : 'unset'));
lightsaber.addBinding(config.lightsaber, 'width', {min: 0.1, max: 4, step: .1})
    .on('change', ({value}) => p('lightsaber-width', value ? `${value}rem` : '0'));
lightsaber.addBinding(config.lightsaber, 'length', {min: 0.1, max: 10, step: .1})
    .on('change', ({value}) => p('lightsaber-length', value ? `${value}rem` : '0'));
lightsaber.addBinding(config.lightsaber, 'gripgap', {min: 0.1, max: 10, step: .1})
    .on('change', ({value}) => p('lightsaber-gripgap', value ? `${value}rem` : '0'));

// apply values from config
Object.keys(config).forEach(section => {
    Object.keys(config[section]).forEach(key => {
        const value = config[section][key];
        config[section][key] = undefined;
        pane.refresh();
        config[section][key] = value;
    });
});

pane.refresh();

config.css:
@property --angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}


:root {
  --c0: #e90663;
  --c1: linear-gradient(-115deg, #1f0303, var(--c0));
  --c2: linear-gradient(55deg, #e90663, black);
  --c3: linear-gradient(45deg, black, var(--c0));
  --c4: linear-gradient(-45deg, #e90663, black);
  --c5: #dfcaaa;
  --c6: #d6c5ab70;
  --size: 40vmin;
  --perspective: 60vmin;
  --d: 20deg;
  --d-x: 1.23vmin;

  font-size: 16px;
}

@keyframes rotate {
  from {
    transform: rotateY(0deg);
  }
  30% {
    transform: rotateY(540deg);
  }

  60% {
    transform: rotateY(720deg);
  }

  to {
    transform: rotateY(1440deg);
  }
}

.scene {
  position: relative;
  perspective: var(--perspective);
  perspective-origin: 40% 50%;
  filter: drop-shadow(0.2vmin 0.4vmin 11.6vmin rgba(255, 255, 255, 0.7));
}

@keyframes particles {
  from {
    --angle: 360deg;
  }
  20% {
    opacity: 1;
  }
  30% {
    --angle: 270deg;
    opacity: 0;
  }

  to {
    --angle: 270deg;
    opacity: 0;
  }
}

@keyframes fireworks {
  from {
    --angle: 360deg;
    transform: rotateX(0) rotateY(0) translateY(0);
  }
  to {
    --angle: 100deg;
    transform: translateX(var(--x)) translateZ(var(--y)) translateY(-100vmin);
  }
}

.fireworks {
  position: absolute;
  transform-style: preserve-3d;
  transform: translateZ(-10vmin);
  .left,
  .right {
    $count: 10;
    --offset-per-surface: calc(360deg / #{$count});
    --radius: 16vmin;
    position: absolute;
    inset: 0;
    --delay-offset: 0s;
    --rotate: -45deg;
    transform: translate(20vmin, 20vmin) rotate(var(--rotate));

    > div {
      position: absolute;
      width: 0.8vmin;
      aspect-ratio: 1;

      @for $i from 1 through ($count + 1) {
        &:nth-child(#{$i - 1}) {
          --index: #{$i - 1};
          --angle-offset: calc(var(--index) * var(--offset-per-surface));
          --x: calc(var(--radius) * cos(var(--angle) + var(--angle-offset)));
          --y: calc(var(--radius) * sin(var(--angle) + var(--angle-offset)));
          animation: fireworks 1.5s ease-in-out infinite;
          animation-delay: calc(0.05s * var(--index) + var(--delay-offset));
          background: hsl(
            calc(var(--angle) + var(--angle-offset))
              100%
              calc(100% - 50% * #{random()})
          );
        }
      }
    }
  }

  .right {
    --rotate: 45deg;
    --delay-offset: 0.35s;
  }
}

.particles {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: translateZ(-10vmin);
  .explosion {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    $count: 16;
    --offset-per-surface: calc(360deg / #{$count});
    --radius: 50vmin;
    --duration-offset: 1s;

    > div {
      position: absolute;
      width: 4vmin;
      aspect-ratio: 1;
      @for $i from 1 through ($count + 1) {
        &:nth-child(#{$i - 1}) {
          --index: #{$i - 1};
          --angle-offset: calc(var(--index) * var(--offset-per-surface));
          --x: calc(var(--radius) * cos(var(--angle) + var(--angle-offset)));
          --y: calc(var(--radius) * sin(var(--angle) + var(--angle-offset)));
          --r: calc(30deg * cos(var(--angle) + var(--angle-offset)));
          animation: explosion
            calc(2s + #{random()} * var(--duration-offset))
            ease-in-out
            infinite;
          animation-delay: 0.3s;
          background: hsl(
            calc(var(--angle) + var(--angle-offset))
              100%
              calc(100% - 60% * #{random()})
          );
        }
      }
    }

    &.depth-1 {
      transform: translateZ(-10vmin);
      --duration-offset: 4s;

      > div {
        --blur: 0.5vmin;
      }
    }

    &.depth-2 {
      transform: translateZ(-20vmin);
      --duration-offset: 4s;

      > div {
        --blur: 4.5vmin;
      }
    }
  }
}

@keyframes explosion {
  from {
    transform: translateX(0) translateY(0) rotate(calc(var(--r) * -1));
    opacity: 0;
    filter: blur(0);
  }
  10% {
    opacity: 1;
  }
  25% {
    transform: translateX(var(--x)) translateY(var(--y)) rotate(var(--r));
    opacity: 0;
    filter: blur(var(--blur, 0));
  }
