@use 'sass:math';
@use 'sass:list';

:root {
  --color-primary: #ee75d2;
  --color-secondary: #75d8ee;
  --color-tertiary: #ffeb3b;
  --color-quaternary: red;
  --color-bg: #0f021f;

}

@property --duration {
  syntax: "<time>";
  inherits: true;
  initial-value: 0s;
}

@property --wall-random {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.walls {
  height: 100vh;
  width: 100vw;
  position: relative;
  perspective: 800px;
  --duration: 18s;
}

.wall {
  filter: url(#blurFilter);
  transform-style: preserve-3d;
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: minmax(1rem, auto);
  grid-auto-flow: column;
  gap: 1rem;
  transform: translate3d(
    calc(var(--wi) * var(--wall-random) * 10rem),
    0,
    calc(6rem * var(--wi))
  );

  &:first-child {
    filter: blur(2rem);
  }

  &:nth-child(2) {
    filter: blur(1rem);
  }

  &:last-child {
    filter: blur(3rem);
  }

  @for $w from 1 through 14 {
    &:nth-child(#{$w}) {
      --wall-index: #{$w};
      --wall-random: #{math.random()};
    }
  }
}

.column {
  display: flex;
  flex-direction: column-reverse;
  position: relative;
  gap: 0.25rem;
  height: 100vh;
  transform: translateY(-120vh);
  animation: fall var(--duration) ease-in-out infinite;
  animation-duration: calc(
    var(--duration) * max(var(--r0), var(--r1), var(--r2))
  );
  animation-delay: calc(var(--wall-random) * var(--r0) * 10s);
  @for $i from 1 through 30 {
    &:nth-child(#{$i}) {
      --r0: #{math.random()};
      --r1: #{math.random()};
      --r2: #{math.random()};
    }
  }
}

.variant {
  display: flex;
  flex-direction: column-reverse;
  mask: linear-gradient(to bottom, transparent 20%, black);
  padding: 1rem 0;

