    transform-style: preserve-3d;
    animation: variant 0.2s ease-in-out infinite;
    position: absolute;
    inset: 0;
  }
}

@keyframes variant {
  from {
    transform: translate3d(0, 0, 0);
    opacity: 0.3;
  }
  50% {
    opacity: 0.2;
    transform: translate3d(0.5rem, -1rem, 1rem);
  }
  to {
    opacity: 0;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes fall {
  60% {
    opacity: 1;
  }
  90% {
    opacity: 0;
  }

  to {
    transform: translateY(2vh);
    opacity: 0;
  }
}

.drop {
  display: grid;
  place-items: center;
  clip-path: polygon(
    50% 0%,
    61% 35%,
    98% 35%,
