// Chromium Browser ☑️

:root {
  --size: 3rem; // size of the fade out effect
}

@property --p1 {
  syntax: "<number>";
  initial-value: 0;
  inherits: true;
}

@property --p2 {
  syntax: "<number>";
  initial-value: 0;
  inherits: true;
}

@keyframes p1 {
  from {
    --p1: 0;
  }
  to {
    --p1: 1;
  }
}

@keyframes p2 {
  from {
    --p2: 1;
  }
  to {
    --p2: 0;
  }
}

.scroll-container {
  width: 60vmin;
  height: 50vmin;
  overflow: hidden auto;
  border-radius: 1rem;
  backdrop-filter: blur(1rem);
  background: rgba(255, 255, 255, 0.1);
  padding: 1rem;
  position: relative;
  animation: p1 linear, p2 linear;
  animation-timeline: scroll(self), scroll(self);
  animation-range: 0 var(--size), contain calc(100% - var(--size));
  animation-fill-mode: both;

  mask: linear-gradient(
    transparent,
    black calc(var(--size) * var(--p1)),
    black calc(100% - var(--size) * var(--p2)),
    transparent
  );
  text-wrap: balance;
  padding: 2rem;
  font-size: 2.5rem;
  letter-spacing: 0.25rem;

  @supports not (animation-timeline: scroll()) {
    mask: unset;
  }
}

