@use 'sass:list';

:root {
  --color-primary: white;
  --color-surface: #030303;
}


@function highlight($gap, $size: 0.25vmin, $color: var(--c)) {
  @return -#{$gap $gap / 1.5 $size $color};
}

@function highlights() {
  $result: ();
  $gap: 0.25vmin;
  $count: 20;
  @for $i from $count through 0 {
    @if ($i == $count) {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.01vmin, var(--c2)),
        "comma"
      );
    } @else if ($i == $count - 1) {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.1vmin, rgba(255, 255, 255, 0.9)),
        "comma"
      );
    } @else {
      $result: list.append(
        $result,
        highlight($i * $gap, 0.025vmin, var(--c)),
        "comma"
      );
    }
  }
  @return $result;
}

.container {
  font-size: 58vmin;
  position: absolute;
  display: grid;
  place-items: center;
  font-family: "Rajdhani", sans-serif;
