    #ee75d2,
    #13f5fa,
    #f6a2f6
  );

  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-fill-color: transparent;

  &::before {
    content: "404";
    position: absolute;
    inset: 0;
    color: transparent;
    --c: color-mix(in srgb, white, transparent 94%);
    --c2: var(--color-surface);
    text-shadow: highlights();
  }
}

